/bin/bash -lc "python3 - <<'PY'
import ast
p='/workspace/tests/test_linkextractors.py'
t=ast.parse(open(p).read())
for node in t.body:
    if isinstance(node, ast.ClassDef):
        methods=[n.name for n in node.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name.startswith('test_')]
        print(node.name, len(methods), methods)
        for sub in node.body:
            if isinstance(sub, ast.ClassDef):
                m=[n.name for n in sub.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name.startswith('test_')]
                print(' ',sub.name,len(m),m)
PY"

